const query = $input.first().json.query || {};
const now = new Date();
const defaultMonth = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
const month = query.month || defaultMonth;
const monthRegex = /^\d{4}-\d{2}$/;
if (!monthRegex.test(month)) {
  throw new Error(`Invalid month format: '${month}'. Expected YYYY-MM.`);
}
return [{ json: { month } }];

const row = $input.first().json;
const data = typeof row.result === 'string' ? JSON.parse(row.result) : row.result;

// Ensure numeric types for stats
if (data.stats) {
  data.stats.today_count = Number(data.stats.today_count || 0);
  data.stats.week_revenue = Number(data.stats.week_revenue || 0);
  data.stats.last_week_revenue = Number(data.stats.last_week_revenue || 0);
  data.stats.unpaid_deposits = Number(data.stats.unpaid_deposits || 0);
  data.stats.available_equipment = Number(data.stats.available_equipment || 0);
}

return [{ json: data }];

const body = $input.first().json.body || $input.first().json;

const id = body.id;
if (!id) {
  throw new Error('Missing required field: id');
}

const allowedFields = [
  'event_date', 'event_time', 'pickup_time', 'delivery_address',
  'city', 'status', 'price', 'deposit_amount', 'deposit_paid',
  'payment_status', 'notes'
];

const setClauses = [];
const values = [];
let paramIndex = 1;

for (const field of allowedFields) {
  if (body[field] !== undefined) {
    setClauses.push(`${field} = $${paramIndex}`);
    values.push(body[field]);
    paramIndex++;
  }
}

if (setClauses.length === 0) {
  throw new Error('No valid fields provided for update');
}

setClauses.push(`updated_at = NOW()`);

const sql = `UPDATE batutynas.bookings SET ${setClauses.join(', ')} WHERE id = $${paramIndex} RETURNING *`;
values.push(id);

return [{ json: { sql, values, id } }];

const rows = $input.all();
if (!rows || rows.length === 0) {
  return [{ json: { success: false, error: 'Booking not found or update failed' } }];
}
const updated = rows[0].json;
return [{ json: { success: true, booking: updated } }];

const body = $input.first().json.body || $input.first().json;
const query = $input.first().json.query || {};

const id = body.id || query.id;
if (!id) {
  throw new Error('Missing required field: id');
}

return [{ json: { id: Number(id) } }];

const rows = $input.all();
const deletedId = $('Parse Delete').first().json.id;

if (!rows || rows.length === 0) {
  return [{ json: { success: false, error: 'Booking not found or already deleted' } }];
}

return [{ json: { success: true, deleted_id: deletedId } }];
